def process():return '''<ol class="it-process"><li><span><strong>Tell us what is happening.</strong> Submit the symptom, device and preferred time. No passwords or codes.</span></li><li><span><strong>We check remote suitability.</strong> Hardware or account-provider restrictions may need a different route.</span></li><li><span><strong>Agree on the price and appointment.</strong> Your time zone, scope and payment terms are confirmed before work.</span></li><li><span><strong>You approve an attended session.</strong> Stay present, control what is shared, and end access whenever you choose.</span></li><li><span><strong>We troubleshoot and explain.</strong> Get a plain-language outcome and next steps, including any limitations.</span></li><li><span><strong>Pay under the agreed terms.</strong> No subscription or extra work without a separate agreement.</span></li></ol>'''
def prices():
 rows=[('Basic Remote Support','C$45','CAD · up to 30 minutes','One straightforward computer or software issue. The suitability check comes first.'),('Extended Remote Support','C$80','CAD · up to 90 minutes','One agreed troubleshooting issue that needs a longer appointment.'),('Password Recovery Assistance','From C$45','CAD · scope agreed first','Official account recovery and login guidance. Access is controlled by the provider, not us.'),('Business / Website / Linux','Custom quote','CAD · written quote before work','Business systems, DNS, HTTPS, Linux and technical projects.')]
