def options(values,default=None):return ''.join(f'<option value="{E(x,quote=True)}"'+(' selected' if x==default else '')+'>'+E(x)+'</option>' for x in values)
def field(label,name,attrs='',hint=''):
 id='support'+''.join(x.title() for x in name.split('_'));return f'<div class="it-field"><label for="{id}">{label}</label><input id="{id}" name="{name}" {attrs}'+(f' aria-describedby="{id}Help"' if hint else '')+'>'+ (f'<p class="it-help" id="{id}Help">{hint}</p>' if hint else '')+'</div>'
def select(label,name,values):return f'<div class="it-field"><label for="support{name.title()}">{label}</label><select id="support{name.title()}" name="{name}" required><option value="">Choose an option</option>{options(values)}</select></div>'
