form+=field('Your name','name','autocomplete="name" required minlength="2" maxlength="100"')+field('Email for our reply','email','type="email" autocomplete="email" required maxlength="254"', 'Use an address you can still access. It need not be the account having problems.')+field('Phone (optional)','phone','type="tel" autocomplete="tel" maxlength="40"')+select('Device','device',DEVICES)+select('Operating system','os',SYSTEMS)+select('Type of problem','issue',ISSUES)
form+='''<div class="it-field full"><label for="supportDescription">What is happening?</label><textarea id="supportDescription" name="description" required minlength="15" maxlength="2000" aria-describedby="descriptionHelp" placeholder="For example: Outlook stopped receiving messages yesterday. Webmail still works. No passwords or codes."></textarea><p class="it-help" id="descriptionHelp">Keep it short: the symptom, when it started, and what you have already tried. No private files or credentials.</p></div>'''
form+=field('Preferred appointment time','preferred_time','required minlength="3" maxlength="160" placeholder="For example: weekdays after 6 pm"','A preference only. We confirm availability by email.')+select('Your time zone','timezone',ZONES)
form+='<div class="it-field full"><label for="supportPlan">Support option</label><select id="supportPlan" name="plan" required>'+options(PLANS,'Please advise')+'</select></div></div>'
form+='''<label class="it-consent" id="ownershipRow" hidden><input type="checkbox" name="owner_confirmed" id="ownerConfirmed"><span>I am the legitimate account owner or authorized administrator. I understand that recovery uses official provider methods and cannot be guaranteed.</span></label><label class="it-consent"><input type="checkbox" name="consent" id="supportConsent" required><span>I authorize JowkariTech to use these details to review and reply to this request. I have read the <a href="/privacy/">privacy notice</a> and <a href="/support-terms/">support terms</a>. This does not grant remote access or subscribe me to marketing.</span></label><div class="it-honeypot" aria-hidden="true"><label for="supportWebsiteCheck">Leave empty</label><input id="supportWebsiteCheck" name="website_check" tabindex="-1" autocomplete="off"></div></fieldset><p class="it-security" id="supportSecurity">Preparing the request service…</p><button id="refreshSecurity" type="button" class="it-inline-link" style="border:0;background:none;cursor:pointer">Refresh security check</button><br><button class="it-btn" type="submit" disabled>Send support request</button><div class="it-status" id="supportStatus" role="status" aria-live="polite" aria-atomic="true" tabindex="-1"></div><noscript><p>JavaScript is needed for the secure request form. Email <a href="mailto:jowkaritech@gmail.com">jowkaritech@gmail.com</a> with a non-sensitive description instead. Do not send passwords or codes.</p></noscript></form><aside class="it-side"><span class="it-kicker">WHAT HAPPENS NEXT</span><h2>A person reviews<br>your request.</h2><p>Mohammad reviews the issue, checks whether remote help is suitable, and replies to agree the scope, price and appointment.</p><p><strong>C$45 CAD</strong> · up to 30 minutes<br><strong>C$80 CAD</strong> · up to 90 minutes<br>Recovery from C$45 CAD; business work by quote.</p><div class="it-callout"><p>No payment on this page.<br>No automatic booking.<br>No unattended remote access.</p></div><p>Cannot use the form?<br><a href="mailto:jowkaritech@gmail.com?subject=Remote%20IT%20support%20request">Email jowkaritech@gmail.com</a><br><a href="tel:+17782661454">(778) 266-1454</a></p><p class="it-fine">Do not use this form for emergency services or an active financial-fraud incident. Contact your bank or the appropriate official response channel directly.</p></aside></div>'''
