 hero='''<section class="it-home" id="remote-it-home"><div class="it-wrap"><div class="it-hero it-hero-grid"><div><span class="it-kicker">REMOTE IT SUPPORT · NORTH VANCOUVER, BC → CANADA</span><h1 class="it-title">Computer problems?<br><em>Get expert remote<br>IT help.</em></h1><p class="it-lead">JowkariTech provides remote computer troubleshooting, software support, account recovery assistance and business IT services across Canada. Based in North Vancouver, BC.</p>'''+actions('Get IT Help')+'''<p class="it-fine">Windows · Outlook · Linux · Wi-Fi · Software<br>Available by remote appointment. Price agreed before work begins.</p></div><aside class="it-appointment"><span class="it-kicker">YOUR COMPUTER. YOU STAY IN CONTROL.</span><h2>A clear price.<br>A practical next step.</h2><div class="it-offer"><span>Basic support<small>Up to 30 minutes · one straightforward issue</small></span><strong>C$45<small>CAD</small></strong></div><div class="it-offer"><span>Extended support<small>Up to 90 minutes · one agreed issue</small></span><strong>C$80<small>CAD</small></strong></div><a class="it-btn orange" href="/request-support/">Describe your problem ↗</a><p class="it-fine">No payment to submit a request.<br>No passwords or codes collected.<br>No remote access without your permission.</p></aside></div><div class="it-trust"><span>BCIT Computer Information Systems Administration diploma</span><span>Attended sessions only</span><span>Based in Canada</span></div>'''
 hero+=section('Back to work. Without the guesswork.','''<div class="it-services"><a class="it-service-row" href="/remote-it-support/"><b>01</b><h3>Computer & software help</h3><p>Windows, slow computers, Outlook, software and remotely diagnosable printer or Wi-Fi issues.</p><span aria-hidden="true">↗</span></a><a class="it-service-row" href="/password-recovery-help/"><b>02</b><h3>Account recovery guidance</h3><p>Official recovery methods for legitimate owners. No security bypasses or access guarantees.</p><span aria-hidden="true">↗</span></a><a class="it-service-row" href="/business-it-support/"><b>03</b><h3>Business, Linux & websites</h3><p>Scoped remote support for business systems, DNS, domains, HTTPS and technical projects.</p><span aria-hidden="true">↗</span></a></div>''')
 hero+=section('A straightforward support process.','<div class="it-split"><div><p>First, we check whether remote help is a good fit. You agree on the price and appointment before troubleshooting begins.</p><div class="it-callout"><p>Hardware that needs physical repair may not be fixable remotely. Account recovery remains subject to the provider\'s rules.</p></div><a class="it-inline-link" href="/support-pricing/">Basic, extended and custom support prices →</a></div><div>'+process()+'</div></div>')
 hero+=section('Hi, I’m Mohammad.','''<div class="it-split"><div><p>I’m Mohammad Jowkari, the founder of JowkariTech in North Vancouver. I have a BCIT diploma in Computer Information Systems Administration and am completing a Bachelor of Technology in Forensic Investigation, Digital Forensics and Cybersecurity.</p><p>My hands-on work includes Windows, Linux, networking, Python, Docker, Caddy, Cloudflare and web applications. I will tell you when a problem needs a specialist or a different kind of service.</p><a class="it-inline-link" href="/about.html">More about JowkariTech →</a></div><div><span class="it-kicker">BEFORE YOU PAY FOR HELP</span><h3>Start with a useful first check.</h3><p>Browse safe starting points for slow Windows computers, Outlook, Wi-Fi and Microsoft account recovery.</p><a class="it-btn secondary" href="/support-resources/">Read the support guides ↗</a></div></div>''')+'</div></section>'
 s.main.insert(0,fragment(hero));s.main['id']='main'
 top=s.select_one('.topline');top.string='Remote IT support across Canada · Based in North Vancouver, BC · Available by appointment'
 s.select_one('header.nav').replace_with(fragment(nav()))
 title='Remote IT Support Canada & Web Services | JowkariTech';desc='Remote computer help across Canada from C$45 CAD. Windows, Outlook, account recovery and business IT by appointment. Based in North Vancouver, BC.'
 s.title.string=title;s.select_one('meta[name=description]')['content']=desc
 for key,val in [('og:title',title),('og:description',desc)]:s.select_one('meta[property="'+key+'"]')['content']=val
